std::uint64_t mesh_key(const RenderDrawCall& d) noexcept{std::uint64_t k=hash64(reinterpret_cast<std::uintptr_t>(d.animated()?d.skinned_mesh.get():d.geometry.get()));k^=hash64(d.part_index+0x9e3779b97f4a7c15ULL);k^=hash64(static_cast<std::uint64_t>(d.animated())+0x243f6a8885a308d3ULL);if(d.animated()&&d.skinned_mesh){k^=hash64(d.skinned_mesh->vertices.size()<<1);k^=hash64(d.skinned_mesh->indices.size()<<2);}else if(d.geometry&&d.part_index<d.geometry->parts.size()){k^=hash64(d.geometry->parts[d.part_index].mesh.vertices.size()<<1);k^=hash64(d.geometry->parts[d.part_index].mesh.indices.size()<<2);}return k?k:1;}
std::uint64_t texture_key(const std::shared_ptr<const Texture2D>& t) noexcept{return t?hash64(reinterpret_cast<std::uintptr_t>(t.get()))^hash64((static_cast<std::uint64_t>(t->width)<<32)|t->height):0;}
