bool OpenGLESRenderer::link_program(const char*,GlUInt vs,const char* fs,GlUInt& program,std::string& error){GlUInt f=0;if(!compile_shader(GL_FRAGMENT_SHADER,fs,f,error))return false;program=api_.CreateProgram();if(!program){api_.DeleteShader(f);error="OpenGL ES glCreateProgram failed";return false;}api_.AttachShader(program,vs);api_.AttachShader(program,f);api_.LinkProgram(program);api_.DeleteShader(vs);api_.DeleteShader(f);GlInt ok=0;api_.GetProgramiv(program,GL_LINK_STATUS,&ok);if(!ok){GlInt len=0;api_.GetProgramiv(program,GL_INFO_LOG_LENGTH,&len);std::vector<char>log(static_cast<std::size_t>(std::max(1,len)),0);GlInt written=0;api_.GetProgramInfoLog(program,len,&written,log.data());error.assign(log.data(),static_cast<std::size_t>(std::max(0,written)));api_.DeleteProgram(program);program=0;return false;}return true;}

