void OpenGLESRenderer::release_meshes()noexcept{for(auto&[_,m]:meshes_){if(m.vertex_buffer&&api_.DeleteBuffers)api_.DeleteBuffers(1,&m.vertex_buffer);if(m.index_buffer&&api_.DeleteBuffers)api_.DeleteBuffers(1,&m.index_buffer);if(m.vao&&api_.DeleteVertexArrays)api_.DeleteVertexArrays(1,&m.vao);}meshes_.clear();}
void OpenGLESRenderer::release_textures()noexcept{for(auto&[_,t]:textures_)if(t.handle&&api_.DeleteTextures)api_.DeleteTextures(1,&t.handle);textures_.clear();}
